function diagonalGroups(matrix) {
  const rows = matrix.length;
  const cols = matrix[0].length;
  const diagonals = Array.from({ length: rows + cols - 1 }, () => []);

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      diagonals[r + c].push(matrix[r][c]);
    }
  }
  return diagonals;
}
